import{_ as o}from"./chunks/a05-job-overview.C-FIcYp3.js";import{_ as t,o as r,c as s,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const a="/rakkii-cars-guide/screenshots/v2/a04-new-job.png",m=JSON.parse('{"title":"1. Open a job","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/01-open-a-job.md","filePath":"desk/job/01-open-a-job.md","lastUpdated":1794643263000}'),i={name:"desk/job/01-open-a-job.md"};function l(g,e,h,c,p,d){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="_1-open-a-job" tabindex="-1">1. Open a job <a class="header-anchor" href="#_1-open-a-job" aria-label="Permalink to &quot;1. Open a job&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Where:</strong> Workshop › <strong>New job</strong> · <strong>Status after:</strong> Booked</p><p>Name, mobile and plate are enough to open a job. Fill in the rest as you learn it.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Press <strong>New job</strong> (in the Workshop menu, or on Job history).</li><li><strong>Customer</strong>: type the <strong>Customer name</strong>. <ul><li>If they&#39;re already on file, the app offers them. Press <strong>Use this customer</strong> (or <strong>Not this customer</strong>).</li><li>Enter the <strong>Mobile</strong>. Add an <strong>Email</strong> if they have one.</li></ul></li><li><strong>Vehicle</strong>: a returning customer&#39;s cars appear as buttons. Tap one, or press <strong>New car</strong> and type the <strong>Plate</strong>, <strong>Make</strong>, <strong>Model</strong> and <strong>Year</strong>.</li><li><strong>Work</strong>: choose the <strong>Work category</strong>, set a <strong>Target date</strong> (when it should be done), and describe the <strong>Services</strong> in plain words.</li><li><strong>How the job came in</strong> is folded. Press <strong>Change</strong> only if you need to set: <ul><li><strong>How they arrived</strong> (Walk-in, Phone, Messenger, Website, Sales)</li><li><strong>Tax</strong> (VAT or Non-VAT)</li><li><strong>Sales advisor</strong> or <strong>Referred by (staff)</strong> (the person who earns commission)</li><li>An outside agent and their <strong>Agent fee (₱)</strong></li></ul></li><li>Insurance job? Set <strong>Job type</strong> to Insurance; the <strong>Insurance</strong> fields appear (<strong>Insurer</strong>, <strong>Claim number</strong>, <strong>Policy number</strong>, <strong>Adjuster</strong>). See <a href="/rakkii-cars-guide/desk/insurance-jobs">Insurance jobs</a>.</li><li>Press <strong>Create job</strong>.</li></ol><p><img src="'+a+'" alt="New job form filled in"></p><p>The job opens at <strong>Booked</strong> (&quot;Job created.&quot;), with a job number such as <code>JOB-20261114-5942</code>. The progress card says &quot;Add work lines to build the quote.&quot; Press <strong>Add work lines →</strong>.</p><p><img src="'+o+'" alt="The new job&#39;s Overview"></p><h2 id="before-you-touch-the-car-intake-checklist" tabindex="-1">Before you touch the car: intake checklist <a class="header-anchor" href="#before-you-touch-the-car-intake-checklist" aria-label="Permalink to &quot;Before you touch the car: intake checklist&quot;">​</a></h2><p>For a car left at the shop, fill the intake checklist so damage and belongings are on record:</p><ol><li>On <strong>Overview</strong>, press <strong>Open checklist</strong> next to <strong>Intake checklist</strong> (or open it from <strong>Files › Documents</strong>).</li><li>The intake checklist opens over the job.</li><li>Tap each damaged panel, set the fuel level, mark what&#39;s in the car, and save.</li><li>Print it for the customer to sign.</li></ol><p>Picking up or delivering the car? Fill the <strong>Pick-up &amp; delivery waiver</strong> in the same place.</p><div class="tip custom-block"><p class="custom-block-title">Car booked for another day?</p><p>Set the <strong>Appointment</strong> from <strong>Overview › Change target date or appointment</strong>. The target date is when work should finish; the appointment is when the car comes in.</p></div><p><strong>Next:</strong> <a href="/rakkii-cars-guide/desk/job/02-work-and-quote">2. Add work and save the quote</a></p>',14)])])}const k=t(i,[["render",l]]);export{m as __pageData,k as default};
